.chapter-container {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #003366;
  --warm: #cc0066;
  --line: #ddd;
  --paper: #f9f9f9;

  font-family: 'Georgia', serif;
  background: var(--paper);
  color: var(--ink);
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  line-height: 1.6;
}

.chapter-header h1 {
  font-size: 2rem;
  color: var(--accent);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.chapter-lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 800px;
}

.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-top: 2rem;
}

@media (max-width: 768px) {
  .split-layout {
    grid-template-columns: 1fr;
  }
}

.evidence-column, .limitation-column {
  background: #fff;
  padding: 1.5rem;
  border-radius: 4px;
  border: 1px solid var(--line);
}

.evidence-column h2, .limitation-column h2 {
  font-size: 1.5rem;
  color: var(--accent);
  margin-bottom: 1rem;
  font-family: 'Courier New', monospace;
}

.evidence-card {
  background: var(--paper);
  padding: 1rem;
  margin-bottom: 1rem;
  border-left: 3px solid var(--accent);
  border-radius: 0 4px 4px 0;
}

.evidence-card h3 {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.evidence-list {
  padding-left: 1.2rem;
  margin: 0.5rem 0;
  font-size: 0.95rem;
}

.evidence-list li {
  margin-bottom: 0.3rem;
}

.bias-indicator {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.5rem 0;
  font-family: 'Courier New', monospace;
}

.bias-label {
  color: var(--muted);
}

.bias-value.positive {
  color: var(--accent);
  font-weight: bold;
}

.stat-highlight {
  text-align: center;
  padding: 0.5rem;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  margin-top: 0.5rem;
}

.stat-value {
  display: block;
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--warm);
  font-family: 'Courier New', monospace;
}

.stat-label {
  font-size: 0.9rem;
  color: var(--muted);
}

.source-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 0.3rem 0.6rem;
  font-size: 0.85rem;
  border-radius: 3px;
  cursor: pointer;
  margin-right: 0.5rem;
  font-family: 'Courier New', monospace;
}

.source-btn:hover {
  opacity: 0.9;
}

.toggle-container {
  display: flex;
  gap: 0.5rem;
  margin: 1rem 0;
}

.toggle-btn {
  flex: 1;
  padding: 0.6rem;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 3px;
  cursor: pointer;
  font-size: 0.95rem;
  transition: all 0.2s;
}

.toggle-btn.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.view-panel {
  display: none;
}

.view-panel.active {
  display: block;
}

.scale-comparison {
  margin: 1.5rem 0;
}

.scale-bar {
  position: relative;
  height: 2rem;
  background: #eee;
  border-radius: 3px;
  margin-bottom: 0.5rem;
  overflow: hidden;
}

.bar {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.5rem;
  color: #fff;
  font-size: 0.8rem;
  font-family: 'Courier New', monospace;
  transition: width 0.5s ease;
}

.lyrics-bar {
  background: var(--warm);
  width: 0.006%;
}

.general-bar {
  background: var(--accent);
  width: 100%;
}

.bar-label {
  position: absolute;
  left: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--ink);
  font-size: 0.85rem;
  z-index: 1;
}

.scale-note {
  font-size: 0.85rem;
  color: var(--muted);
  font-style: italic;
}

.test-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
  margin: 1rem 0;
}

@media (max-width: 480px) {
  .test-grid {
    grid-template-columns: 1fr;
  }
}

.test-btn {
  background: #fff;
  border: 1px solid var(--line);
  padding: 0.8rem;
  border-radius: 3px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.2s;
  text-align: center;
}

.test-btn:hover {
  border-color: var(--warm);
  background: #fff5f8;
}

.test-btn small {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
  margin-top: 0.3rem;
}

.test-result {
  background: var(--paper);
  padding: 1rem;
  border-radius: 4px;
  margin-top: 1rem;
  border: 1px solid var(--line);
}

.test-result.hidden {
  display: none;
}

.result-comparison {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
  margin: 1rem 0;
  font-family: 'Courier New', monospace;
}

.result-item {
  background: #fff;
  padding: 0.6rem;
  border-radius: 3px;
  text-align: center;
  border: 1px solid var(--line);
}

.result-item.highlight {
  border-color: var(--accent);
  background: #f0f4ff;
}

.result-label {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  margin-bottom: 0.3rem;
}

.result-value {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--ink);
}

.error-explanation {
  font-size: 0.9rem;
  color: var(--muted);
  line-height: 1.5;
  margin: 0.5rem 0;
}

.reset-btn {
  background: var(--muted);
  color: #fff;
  border: none;
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
  border-radius: 3px;
  cursor: pointer;
  margin-top: 0.5rem;
}

.reset-btn:hover {
  opacity: 0.9;
}

.takeaway-box {
  background: #fff;
  padding: 1rem;
  border-radius: 4px;
  border: 1px solid var(--line);
  margin-top: 2rem;
}

.takeaway-box h4 {
  color: var(--accent);
  margin-bottom: 0.5rem;
  font-family: 'Courier New', monospace;
}

.chapter-footer {
  margin-top: 2rem;
}

@media (prefers-reduced-motion: reduce) {
  .bar, .toggle-btn, .test-btn {
    transition: none;
  }
}

javascript:
(function() {
  'use strict';

  // 从 runtime_data 获取表格数据
  const tables = window.paperMindData?.tables || [];
  const p4Table = tables.find(t => t.id === 'p4-table-1');

  if (!p4Table) {
    console.error('Table p4-table-1 not found');
    return;
  }

  // 解析表格数据为对象
  const testData = {};
  p4Table.rows.forEach(row => {
    const testNo = row.values['Test no.'];
    testData[testNo] = {
      target: row.values['Target Words'],
      ft: parseFloat(row.values['FT']),
      ca: parseFloat(row.values['CA']),
      iat: parseFloat(row.values['IAT'])
    };
  });

  // DOM 元素
  const viewToggle = document.getElementById('view-toggle');
  const viewToggleDetail = document.getElementById('view-toggle-detail');
  const overviewPanel = document.getElementById('limitation-overview');
  const detailPanel = document.getElementById('limitation-detail');
  const testButtons = document.querySelectorAll('.test-btn');
  const testResult = document.getElementById('test-result');
  const testTitle = document.getElementById('test-title');
  const ftValue = document.getElementById('ft-value');
  const caValue = document.getElementById('ca-value');
  const iatValue = document.getElementById('iat-value');
  const errorExplanation = document.getElementById('error-explanation');
  const resetBtn = document.getElementById('reset-test');

  // 视图切换
  function switchView(view) {
    if (view === 'overview') {
      overviewPanel.classList.add('active');
      detailPanel.classList.remove('active');
      viewToggle.classList.add('active');
      viewToggleDetail.classList.remove('active');
    } else {
      overviewPanel.classList.remove('active');
      detailPanel.classList.add('active');
      viewToggle.classList.remove('active');
      viewToggleDetail.classList.add('active');
    }
  }

  viewToggle.addEventListener('click', () => switchView('overview'));
  viewToggleDetail.addEventListener('click', () => switchView('detail'));

  // 测试按钮点击处理
  testButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const testNo = btn.getAttribute('data-test');
      const data = testData[testNo];

      if (!data) return;

      // 更新标题
      testTitle.textContent = `测试${testNo}: ${data.target}`;

      // 更新数值
      ftValue.textContent = data.ft.toFixed(2);
      caValue.textContent = data.ca.toFixed(2);
      iatValue.textContent = data.iat.toFixed(2);

      // 计算误差
      const ftError = Math.abs(data.ft - data.iat);
      const caError = Math.abs(data.ca - data.iat);

      // 生成解释文本
      let explanation = '';
      if (testNo === '3' || testNo === '8') {
        explanation = `歌词数据集中缺乏足够的${data.target.includes('人名') ? '人名' : '特定名称'}实例，导致 fastText 生成的词向量不准确。通用语料库 (CA) 因数据规模更大，结果更接近人类基准 (IAT)。`;
      } else if (testNo === '6') {
        explanation = `歌词数据集中缺乏科学相关术语，导致词向量表示不准。通用语料库包含更多科学词汇，因此结果更可靠。`;
      }

      errorExplanation.textContent = explanation;

      // 显示结果
      testResult.classList.remove('hidden');
    });
  });

  // 复位按钮
  resetBtn.addEventListener('click', () => {
    testResult.classList.add('hidden');
  });

  // 键盘支持
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !testResult.classList.contains('hidden')) {
      testResult.classList.add('hidden');
    }
  });

  // 初始化：确保默认视图正确
  switchView('overview');
})();
